"""v8.6 : check-up du matin (FC réveil vs référence, courbatures, énergie, douleurs) → forme, séances de course adaptées (🩹), muscu (zones), journal du corps ; chaussures (Strava gear + paires saisies, km, usage, alerte, retrait)."""
import os, json
APP=os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)),'..'))
import asyncio, subprocess, time
from playwright.async_api import async_playwright
async def m():
  async with async_playwright() as p:
    br=await p.chromium.launch(); ctx=await br.new_context(viewport={'width':390,'height':844},device_scale_factor=2)
    A=await ctx.new_page(); errs=[]; A.on('pageerror',lambda x:errs.append(str(x)))
    await A.route('https://fonts.**',lambda r:r.abort())
    await A.goto('http://127.0.0.1:8765/index.html')
    await A.evaluate("loadDemo();const d=dayIdx();S.sched={...SD(),q:d,e:(d+1)%7,l:(d+5)%7,A:(d+2)%7,B:(d+3)%7,C:(d+4)%7};save();renderAll();showTab('today')"); await A.wait_for_timeout(200)
    print('banner', await A.evaluate("$('[data-page=today]').innerText.includes('Check-up du matin')"))
    r0=await A.evaluate("readiness().sc"); print('sc0', r0)
    # référence FC : 10 jours à ~50
    await A.evaluate("S.check={};for(let i=1;i<=10;i++){const d=new Date();d.setDate(d.getDate()-i);S.check[iso(d)]={fc:49+i%3,sore:0,mood:2,pain:[],t:1};}save()")
    print('base', await A.evaluate("fcBase()"))
    await A.evaluate("openCheck()"); await A.fill('#ck_fc','59')
    await A.locator('#sheetBody .chip:has-text("Marquées")').click(); await A.locator('#sheetBody .chip:has-text("Bof")').click()
    for _ in range(2): await A.locator('#sheetBody .chip:has-text("Genou")').click()
    await A.locator('#sheetBody .chip:has-text("Épaule")').click(); await A.locator('#sheetBody .chip:has-text("Épaule")').click()
    await A.screenshot(path='k_sheet.png')
    await A.locator('#sheetBody button:has-text("Enregistrer")').click(); await A.wait_for_timeout(150)
    print('saved', await A.evaluate("JSON.stringify(S.check[iso(new Date())])"))
    print('effect', await A.evaluate("JSON.stringify(checkEffect())"), 'sc', await A.evaluate("readiness().sc"), 'why', await A.evaluate("readiness().why.filter(x=>/FC|courb|douleur/.test(x)).join(' | ')"))
    print('ctx pains', await A.evaluate("CTX().pains.join(',')"))
    t=await A.evaluate("JSON.stringify(daySessions(weekIdx(),dayIdx(),'run').map(o=>[strip(o.t).slice(0,30),o.pain||0,!!o.timer]))"); print('today run', t)
    print('tomorrow', await A.evaluate("(()=>{const dt=new Date();dt.setDate(dt.getDate()+1);return daySessions(weekIdx(dt),dayIdx(dt),'run').map(o=>o.pain||0).join(',')})()"), 'in 3 days', await A.evaluate("(()=>{const dt=new Date();dt.setDate(dt.getDate()+3);return daySessions(weekIdx(dt),dayIdx(dt),'run').map(o=>o.pain||0).join(',')||'-'})()"))
    await A.evaluate("CK={...S.check[iso(new Date())],d:iso(new Date())};CK.pain=[{z:'genou',lv:3}];saveCheck()")
    print('lv3', await A.evaluate("daySessions(weekIdx(),dayIdx(),'run').map(o=>strip(o.s).slice(0,40)).join(' | ')"))
    await A.evaluate("renderAll();showTab('today')"); await A.wait_for_timeout(150); await A.screenshot(path='k_today.png',full_page=True)
    await A.evaluate("showTab('forme')"); await A.wait_for_timeout(150)
    print('journal', await A.evaluate("$('[data-page=forme]').innerText.includes('Journal du corps')"), await A.evaluate("document.querySelectorAll('[data-page=forme] .pj-r i').length"))
    await A.locator('[data-page=forme] .card:has-text("Journal du corps")').screenshot(path='k_journal.png')
    print('synced', await A.evaluate("'check' in syncPayload().data"))
    await A.evaluate("openCheck()"); A.on('dialog',lambda d: asyncio.ensure_future(d.accept())); await A.locator('#sheetBody button:has-text("Effacer")').click(); await A.wait_for_timeout(100)
    print('deleted', await A.evaluate("!S.check[iso(new Date())]"), await A.evaluate("S.del.check.includes(iso(new Date()))"), 'no pain overlay', await A.evaluate("daySessions(weekIdx(),dayIdx(),'run').every(o=>!o.pain)"))
    # chaussures
    await A.evaluate("""(()=>{S.gearStrava=[{id:'g1',name:'Speedgoat 6',km:655,primary:true,retired:false},{id:'g2',name:'Pegasus 41',km:120,primary:false,retired:false}];const R=getRuns();R.forEach((r,i)=>r.gear_id=i%3?'g1':'g2');save();renderAll();})()""")
    print('shoes', await A.evaluate("JSON.stringify(shoesAll().map(s=>[s.name,Math.round(s.km),s.runs.length]))"), 'alert', await A.evaluate("(shoeAlert()||{}).name"))
    await A.evaluate("showTab('today')"); print('today banner', await A.evaluate("$('[data-page=today]').innerText.includes('Speedgoat 6')"))
    await A.evaluate("openShoes()"); await A.wait_for_timeout(100); print('use', await A.evaluate("$('#sheetBody').innerText.includes('sorties ·')")); await A.screenshot(path='k_shoes.png')
    await A.evaluate("shoeEdit()"); await A.fill('#sh_n','Mafate Speed 4'); await A.fill('#sh_k','80'); await A.locator('#sheetBody button:has-text("Enregistrer")').click(); await A.wait_for_timeout(100)
    print('manual', await A.evaluate("JSON.stringify(shoesAll().filter(s=>s.src==='manuel').map(s=>[s.name,Math.round(s.km),s.primary]))"))
    await A.evaluate("shoeSet('g1','retired',true)"); print('retired', await A.evaluate("shoeAlert()===null"), 'nosync gear', await A.evaluate("!('gearStrava' in syncPayload().data)&&('shoes' in syncPayload().data)"))
    print('ERR',errs); await br.close()
srv=subprocess.Popen(['python3','-m','http.server','8765'],cwd=APP,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL); time.sleep(1)
try: asyncio.run(m())
finally: srv.terminate()
